            Self::Html(_) | Self::Js(_) => true,
            Self::Css(_)
            | Self::Graphql(_)
            | Self::Json(_)
            | Self::Grit(_)
            | Self::Markdown(_)
            | Self::Ignore
            | Self::Unknown => false,
        }
    }
}

